package net.fabricmc.fabric.api.client.screen.v1;
import java.util.Map;
import java.util.WeakHashMap;

import net.fabricmc.fabric.api.event.Event;
import net.fabricmc.fabric.api.event.EventFactory;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.screens.Screen;

/** Fabric API: keys pressed/released in a screen (Omniloader stand-in; generated by tools/gen-fabric-events.py). */
public final class ScreenKeyboardEvents {
    private ScreenKeyboardEvents() {}

    /** Per-screen events, forgotten when the screen goes away. */
    private static final Map<Screen, Map<String, Event<?>>> PER_SCREEN = new WeakHashMap<>();

    @SuppressWarnings("unchecked")
    private static synchronized <T> Event<T> of(Screen s, String k, java.util.function.Supplier<Event<T>> f) {
        return (Event<T>) PER_SCREEN.computeIfAbsent(s, x -> new java.util.HashMap<>()).computeIfAbsent(k, x -> f.get());
    }

    /** Omniloader: drop a screen's per-screen listeners (Fabric does this each time a screen is set up again). */
    public static synchronized void clear(Screen s) { PER_SCREEN.remove(s); }

    /** Omniloader: the per-screen event if anyone registered on it. */
    @SuppressWarnings("unchecked")
    public static synchronized <T> Event<T> peek(Screen s, String k) { var m = PER_SCREEN.get(s); return m == null ? null : (Event<T>) m.get(k); }

    public static Event<AllowKeyPress> allowKeyPress(Screen forScreen) { return of(forScreen, "allowKeyPress", () -> EventFactory.createArrayBacked(AllowKeyPress.class, ls -> (screen, key, scancode, modifiers) -> { for (AllowKeyPress l : ls) if (!l.allowKeyPress(screen, key, scancode, modifiers)) return false; return true; })); }
    public static Event<BeforeKeyPress> beforeKeyPress(Screen forScreen) { return of(forScreen, "beforeKeyPress", () -> EventFactory.createArrayBacked(BeforeKeyPress.class, ls -> (screen, key, scancode, modifiers) -> { for (BeforeKeyPress l : ls) l.beforeKeyPress(screen, key, scancode, modifiers); })); }
    public static Event<AfterKeyPress> afterKeyPress(Screen forScreen) { return of(forScreen, "afterKeyPress", () -> EventFactory.createArrayBacked(AfterKeyPress.class, ls -> (screen, key, scancode, modifiers) -> { for (AfterKeyPress l : ls) l.afterKeyPress(screen, key, scancode, modifiers); })); }
    public static Event<AllowKeyRelease> allowKeyRelease(Screen forScreen) { return of(forScreen, "allowKeyRelease", () -> EventFactory.createArrayBacked(AllowKeyRelease.class, ls -> (screen, key, scancode, modifiers) -> { for (AllowKeyRelease l : ls) if (!l.allowKeyRelease(screen, key, scancode, modifiers)) return false; return true; })); }
    public static Event<BeforeKeyRelease> beforeKeyRelease(Screen forScreen) { return of(forScreen, "beforeKeyRelease", () -> EventFactory.createArrayBacked(BeforeKeyRelease.class, ls -> (screen, key, scancode, modifiers) -> { for (BeforeKeyRelease l : ls) l.beforeKeyRelease(screen, key, scancode, modifiers); })); }
    public static Event<AfterKeyRelease> afterKeyRelease(Screen forScreen) { return of(forScreen, "afterKeyRelease", () -> EventFactory.createArrayBacked(AfterKeyRelease.class, ls -> (screen, key, scancode, modifiers) -> { for (AfterKeyRelease l : ls) l.afterKeyRelease(screen, key, scancode, modifiers); })); }

    @FunctionalInterface public interface AllowKeyPress { boolean allowKeyPress(Screen screen, int key, int scancode, int modifiers); }
    @FunctionalInterface public interface BeforeKeyPress { void beforeKeyPress(Screen screen, int key, int scancode, int modifiers); }
    @FunctionalInterface public interface AfterKeyPress { void afterKeyPress(Screen screen, int key, int scancode, int modifiers); }
    @FunctionalInterface public interface AllowKeyRelease { boolean allowKeyRelease(Screen screen, int key, int scancode, int modifiers); }
    @FunctionalInterface public interface BeforeKeyRelease { void beforeKeyRelease(Screen screen, int key, int scancode, int modifiers); }
    @FunctionalInterface public interface AfterKeyRelease { void afterKeyRelease(Screen screen, int key, int scancode, int modifiers); }
}
